// Package tsgen writes TypeScript declarations for Go types that are sent
// as JSON, following encoding/json's rules for names, omission and nulls.
package tsgen

import (
	"encoding"
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode"
)

// Header is the first line of every generated file.
const Header = "// Code generated by internal/tsgen; DO NOT EDIT.\n"

var (
	textMarshaler = reflect.TypeFor[encoding.TextMarshaler]()
	jsonMarshaler = reflect.TypeFor[json.Marshaler]()
	timeType      = reflect.TypeFor[time.Time]()
	rawType       = reflect.TypeFor[json.RawMessage]()
)

// Result is the generated source and what it holds.
type Result struct {
	Source     []byte
	Interfaces int
	Aliases    int
}

type field struct {
	name     string
	typ      reflect.Type
	optional bool
	quoted   bool
	depth    int
	tagged   bool
}

type gen struct {
	srcDirs map[string]string
	consts  map[string]map[string]*enum
	order   []reflect.Type
	seen    map[reflect.Type]bool
	names   map[reflect.Type]string
	err     error
}

type enum struct {
	lits    []string
	literal bool
}

// Generate declares roots and every named type reachable from them, in
// discovery order. srcDirs maps a package path to the directory whose
// non-test files hold the const blocks of that package's named types.
func Generate(roots []reflect.Type, srcDirs map[string]string) (Result, error) {
	g := &gen{srcDirs: srcDirs, consts: map[string]map[string]*enum{}, seen: map[reflect.Type]bool{}}
	for _, r := range roots {
		g.walk(r)
	}
	if g.err != nil {
		return Result{}, g.err
	}
	g.assignNames()

	var b strings.Builder
	b.WriteString(Header)
	var res Result
	for _, t := range g.order {
		b.WriteString("\n")
		if t.Kind() == reflect.Struct {
			res.Interfaces++
			g.writeInterface(&b, t)
		} else {
			res.Aliases++
			g.writeAlias(&b, t)
		}
	}
	if g.err != nil {
		return Result{}, g.err
	}
	res.Source = []byte(b.String())
	return res, nil
}

func (g *gen) fail(format string, args ...any) {
	if g.err == nil {
		g.err = fmt.Errorf(format, args...)
	}
}

func (g *gen) typeID(t reflect.Type) string {
	if t.PkgPath() == "" {
		return t.String()
	}
	return t.PkgPath() + "." + t.Name()
}

// opaque reports a type that is a string on the wire whatever its Go shape.
func opaque(t reflect.Type) bool {
	if t == timeType {
		return true
	}
	return t.Implements(textMarshaler) || reflect.PointerTo(t).Implements(textMarshaler)
}

func (g *gen) checkMarshaler(t reflect.Type) bool {
	if t == timeType || t == rawType {
		return false
	}
	if t.Implements(jsonMarshaler) || reflect.PointerTo(t).Implements(jsonMarshaler) {
		g.fail("tsgen: %s has its own MarshalJSON; decide its TypeScript type by hand", g.typeID(t))
		return true
	}
	return false
}

// structFields applies encoding/json's field selection, with embedded
// structs flattened.
func (g *gen) structFields(t reflect.Type) []field {
	var all []field
	g.collect(t, 0, false, map[reflect.Type]bool{}, &all)
	best := map[string]int{}
	count := map[string]int{}
	for _, f := range all {
		d, ok := best[f.name]
		switch {
		case !ok || f.depth < d:
			best[f.name], count[f.name] = f.depth, 1
		case f.depth == d:
			count[f.name]++
		}
	}
	var out []field
	for _, f := range all {
		if f.depth != best[f.name] {
			continue
		}
		if count[f.name] > 1 {
			tagged := 0
			for _, o := range all {
				if o.name == f.name && o.depth == f.depth && o.tagged {
					tagged++
				}
			}
			if tagged != 1 || !f.tagged {
				continue
			}
		}
		out = append(out, f)
	}
	return out
}

func (g *gen) collect(t reflect.Type, depth int, optional bool, visiting map[reflect.Type]bool, out *[]field) {
	if visiting[t] {
		return
	}
	visiting[t] = true
	defer delete(visiting, t)
	for i := range t.NumField() {
		sf := t.Field(i)
		tag, hasTag := sf.Tag.Lookup("json")
		if tag == "-" {
			continue
		}
		name, opts, _ := strings.Cut(tag, ",")
		if sf.Anonymous {
			et := sf.Type
			if et.Kind() == reflect.Pointer {
				et = et.Elem()
			}
			if !sf.IsExported() && et.Kind() != reflect.Struct {
				continue
			}
			if name == "" && et.Kind() == reflect.Struct && !opaque(et) {
				g.collect(et, depth+1, optional || sf.Type.Kind() == reflect.Pointer, visiting, out)
				continue
			}
		} else if !sf.IsExported() {
			continue
		}
		f := field{name: name, typ: sf.Type, depth: depth, tagged: hasTag && name != "", optional: optional}
		if f.name == "" {
			f.name = sf.Name
		}
		for _, o := range strings.Split(opts, ",") {
			switch o {
			case "omitempty", "omitzero":
				f.optional = true
			case "string":
				f.quoted = true
			}
		}
		*out = append(*out, f)
	}
}

// walk records the named types reachable through t.
func (g *gen) walk(t reflect.Type) {
	if g.err != nil {
		return
	}
	if t.Kind() == reflect.Pointer {
		g.walk(t.Elem())
		return
	}
	if opaque(t) || t == rawType {
		return
	}
	named := t.Name() != ""
	if named && strings.Contains(t.Name(), "[") {
		g.fail("tsgen: generic type %s is not supported", t)
		return
	}
	if named && g.checkMarshaler(t) {
		return
	}
	if t.Kind() == reflect.Struct {
		if !named {
			g.fail("tsgen: anonymous struct %s needs a name", t)
			return
		}
		if g.seen[t] {
			return
		}
		g.seen[t] = true
		g.order = append(g.order, t)
		for _, f := range g.structFields(t) {
			g.walk(f.typ)
		}
		return
	}
	if _, ok := g.srcDirs[t.PkgPath()]; named && ok && !g.seen[t] {
		g.seen[t] = true
		g.order = append(g.order, t)
	}
	switch t.Kind() {
	case reflect.Slice, reflect.Array:
		if t.Elem().Kind() != reflect.Uint8 {
			g.walk(t.Elem())
		}
	case reflect.Map:
		g.walk(t.Elem())
	}
}

func (g *gen) assignNames() {
	count := map[string]int{}
	for _, t := range g.order {
		count[t.Name()]++
	}
	g.names = map[reflect.Type]string{}
	used := map[string]bool{}
	for _, t := range g.order {
		n := t.Name()
		if count[n] > 1 {
			p := t.PkgPath()
			p = p[strings.LastIndex(p, "/")+1:]
			n = camel(p) + n
		}
		for used[n] {
			g.fail("tsgen: name collision on %s", n)
			break
		}
		used[n] = true
		g.names[t] = n
	}
}

func camel(s string) string {
	var b strings.Builder
	up := true
	for _, r := range s {
		if !unicode.IsLetter(r) && !unicode.IsDigit(r) {
			up = true
			continue
		}
		if up {
			r = unicode.ToUpper(r)
			up = false
		}
		b.WriteRune(r)
	}
	return b.String()
}

func (g *gen) writeInterface(b *strings.Builder, t reflect.Type) {
	fmt.Fprintf(b, "export interface %s {\n", g.names[t])
	for _, f := range g.structFields(t) {
		expr, nullable := g.ref(f.typ)
		if f.quoted {
			expr, nullable = "string", false
		}
		key := propName(f.name)
		if f.optional {
			// An omitted field is never null: omission replaces it.
			fmt.Fprintf(b, "  %s?: %s\n", key, expr)
			continue
		}
		if nullable {
			expr += " | null"
		}
		if !f.quoted && g.zeroOutsideUnion(f.typ) {
			expr += " | ''"
		}
		fmt.Fprintf(b, "  %s: %s\n", key, expr)
	}
	b.WriteString("}\n")
}

func (g *gen) writeAlias(b *strings.Builder, t reflect.Type) {
	expr, _ := g.kindExpr(t)
	if e := g.enumOf(t); e != nil && e.literal && t.Kind() == reflect.String {
		parts := make([]string, len(e.lits))
		for i, l := range e.lits {
			parts[i] = quote(l)
		}
		expr = strings.Join(parts, " | ")
	}
	fmt.Fprintf(b, "export type %s = %s\n", g.names[t], expr)
}

// zeroOutsideUnion reports a literal union that lacks "", which a required
// field of that type still holds as Go's zero value.
func (g *gen) zeroOutsideUnion(t reflect.Type) bool {
	if _, ok := g.names[t]; !ok || t.Kind() != reflect.String {
		return false
	}
	e := g.enumOf(t)
	return e != nil && e.literal && len(e.lits) > 0 && !contains(e.lits, "")
}

// ref returns the TypeScript for t and whether it can be null.
func (g *gen) ref(t reflect.Type) (string, bool) {
	if t.Kind() == reflect.Pointer {
		e, _ := g.ref(t.Elem())
		return e, true
	}
	if t == timeType || opaque(t) {
		return "string", false
	}
	if t == rawType {
		return "unknown", false
	}
	if g.checkMarshaler(t) {
		return "unknown", false
	}
	if n, ok := g.names[t]; ok {
		return n, nullableKind(t.Kind())
	}
	return g.kindExpr(t)
}

// kindExpr is the TypeScript for the structure of t, ignoring its name.
func (g *gen) kindExpr(t reflect.Type) (string, bool) {
	switch t.Kind() {
	case reflect.String:
		return "string", false
	case reflect.Bool:
		return "boolean", false
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64,
		reflect.Float32, reflect.Float64:
		return "number", false
	case reflect.Interface:
		if t.NumMethod() != 0 {
			g.fail("tsgen: non-empty interface %s", t)
		}
		return "unknown", false
	case reflect.Slice:
		if t.Elem().Kind() == reflect.Uint8 {
			return "string", true
		}
		return g.list(t.Elem()), true
	case reflect.Array:
		return g.list(t.Elem()), false
	case reflect.Map:
		k := t.Key()
		if k.Kind() != reflect.String && !opaque(k) && !isInt(k.Kind()) {
			g.fail("tsgen: map key %s is not a string, integer or text marshaler", k)
		}
		v, n := g.ref(t.Elem())
		if n {
			v += " | null"
		}
		return "Record<string, " + v + ">", true
	}
	g.fail("tsgen: no TypeScript for %s", t)
	return "unknown", false
}

func (g *gen) list(elem reflect.Type) string {
	e, n := g.ref(elem)
	if n {
		return "(" + e + " | null)[]"
	}
	return e + "[]"
}

func nullableKind(k reflect.Kind) bool {
	return k == reflect.Slice || k == reflect.Map || k == reflect.Pointer
}

func isInt(k reflect.Kind) bool {
	return k >= reflect.Int && k <= reflect.Uint64
}

func propName(s string) string {
	ok := s != ""
	for i, r := range s {
		if r != '_' && r != '$' && !unicode.IsLetter(r) && (i == 0 || !unicode.IsDigit(r)) {
			ok = false
		}
	}
	if ok {
		return s
	}
	return quote(s)
}

func quote(s string) string {
	s = strings.NewReplacer(`\`, `\\`, `'`, `\'`, "\n", `\n`).Replace(s)
	return "'" + s + "'"
}

// enumOf reads the const block values of a named type from its package.
func (g *gen) enumOf(t reflect.Type) *enum {
	dir, ok := g.srcDirs[t.PkgPath()]
	if !ok {
		return nil
	}
	m, ok := g.consts[t.PkgPath()]
	if !ok {
		var err error
		m, err = readConsts(dir)
		if err != nil {
			g.fail("tsgen: %v", err)
		}
		g.consts[t.PkgPath()] = m
	}
	return m[t.Name()]
}

// readConsts maps a type name to the string literals of its consts. An
// iota block, or any value that is not a literal, makes the type plain.
func readConsts(dir string) (map[string]*enum, error) {
	files, err := filepath.Glob(filepath.Join(dir, "*.go"))
	if err != nil {
		return nil, err
	}
	sort.Strings(files)
	out := map[string]*enum{}
	fset := token.NewFileSet()
	for _, name := range files {
		if strings.HasSuffix(name, "_test.go") {
			continue
		}
		src, err := os.ReadFile(name)
		if err != nil {
			return nil, err
		}
		f, err := parser.ParseFile(fset, name, src, 0)
		if err != nil {
			return nil, err
		}
		for _, d := range f.Decls {
			gd, ok := d.(*ast.GenDecl)
			if !ok || gd.Tok != token.CONST {
				continue
			}
			var last string
			for _, s := range gd.Specs {
				vs := s.(*ast.ValueSpec)
				if id, ok := vs.Type.(*ast.Ident); ok {
					last = id.Name
				} else if vs.Type != nil {
					last = ""
				}
				if last == "" {
					continue
				}
				e := out[last]
				if e == nil {
					e = &enum{literal: true}
					out[last] = e
				}
				if len(vs.Values) == 0 || len(vs.Values) != len(vs.Names) {
					e.literal = false
					continue
				}
				for _, v := range vs.Values {
					bl, ok := v.(*ast.BasicLit)
					if !ok || bl.Kind != token.STRING {
						e.literal = false
						continue
					}
					lit, err := strconv.Unquote(bl.Value)
					if err != nil {
						return nil, err
					}
					if !contains(e.lits, lit) {
						e.lits = append(e.lits, lit)
					}
				}
			}
		}
	}
	return out, nil
}

func contains(s []string, v string) bool {
	for _, x := range s {
		if x == v {
			return true
		}
	}
	return false
}
